  v = `Opcjonalne: możesz wybrać, czy chcesz zaprosić innych producentów, by załączyli swoje gry w twoim zestawie. Jako właściciel zestawu jesteś odpowiedzialny za koordynację z innymi producentami oraz jesteś jedyną osobą, która może opublikować zestaw w Sklepie Steam. Zaproszone strony mogą wybrać, które gry/pakiety mają zostać załączone. Za każdym razem, gdy pakiet jest dodawany do zestawu lub zmienia się procent zniżki, wszyscy współpracujący muszą zatwierdzić fakt załączenia swojej gry w zestawie, zanim zostanie on opublikowany.`,
