  E = `Tutaj znajdziesz strony wyprzedaży na Steam, które zawierają przynajmniej jedną grę, do której posiadasz uprawnienia do zarządzania. W niektórych przypadkach za te strony odpowiadają organizatorzy wydarzeń, a czasami Valve w ramach zorganizowanych wydarzeń promocyjnych.`,
  D = `Są to wszystkie aktywne i przygotowane strony wyprzedaży stworzone albo przez Valve, albo zatwierdzony podmiot zewnętrzny. Aby skonfigurować nowego partnera tak, by był on w stanie tworzyć swoją własną stronę wyprzedaży, %1$s. Możesz przekazać swojemu partnerowi %2$s.`,
