  at = `Utwórz nowe wydarzenie wyprzedaży`,
  ot = `Wybierz odpowiednią grupę społeczności, by utworzyć pod nią wydarzenie i wyprzedaż`,
  st = `Wprowadź nazwę grupy lub URL sklepu`,
  ct = `Wyprzedaż musi zostać stworzona w oparciu o stronę główną twórcy (inaczej zwaną stroną producenta/wydawcy/serii). Wyszukaj nazwę strony głównej twórcy poniżej:`,
  lt = `Wprowadź albo nazwę grupy powiązanej ze stroną główną twórcy, albo URL sklepu, jeżeli jest to przeznaczone dla kuratora lub niedawno utworzonej grupy społeczności.`,
  ut = `1. Wybrany twórca, który przeprowadzi wydarzenie wyprzedaży:`,
  dt = `Wyczyść twórcę i wyszukaj ponownie, by znaleźć inną stronę główną twórcy`,
  ft = `2. Zweryfikuj, że ta strona główna twórcy posiada włączone wydarzenia partnerskie:`,
  pt = `Ta strona główna twórcy musi dołączyć do bety wydarzeń partnerskich, by użyć funkcji wyprzedaży. Tego działania nie można cofnąć. Zmieni to edytor do zamieszczania ogłoszeń i uniemożliwi tworzenie połączonych wydarzeń. %1$s`,
  mt = `3. Wprowadź minimalne wymagane informacje:`,
  ht = `Opisowa nazwa wydarzenia`,
  gt = `Jest to długa nazwa wydarzenia skierowana do użytkowników. Może ona zawierać partnera i daty wydarzenia.`,
