  vs = `Zamieść jako małą aktualizację`,
  ys = `Prześlij tłumaczenie w języku „Steam China – chiński uproszczony” by ta lista zmian pojawiła się na Steam China.`,
  bs = `Ta lista zmian zostanie również zamieszczona na Steam China z użyciem tekstu w języku „Steam China – chiński uproszczony”.`,
  xs = `Wprowadź listę zmian (np. punktowa lista zmian w kompilacji właśnie ustawionej jako aktywną)`,
