  dc = `%2$s rozpocznie się %3$s. Jeśli chcesz uczestniczyć w tym wydarzeniu, to długość oferty dnia nie powinna przekroczyć %1$s dnia.`,
  fc = `%2$s rozpocznie się %3$s. Jeśli chcesz uczestniczyć w tym wydarzeniu, to długość oferty dnia nie powinna przekroczyć %1$s dni.`,
