  gc = `Produkt do wyróżnienia:`,
  _c = `Ten produkt pojawi się w polu oferty dnia wraz ze swoją ceną, zniżką i obrazem miniatury. W większości wypadków pozostawienie domyślnego wyboru gry będzie wystarczające.`,
