  sl = `Wprowadź zniżki`,
  cl = `Edytuj zniżki`,
  ll = `Musisz najpierw wybrać datę`,
  ul = `Oferta dnia jest AKTYWNA!`,
  dl = `Oferta dnia została zakończona w dniu %1$s`,
  fl = `Ta oferta dnia nie była wyświetlana, ponieważ nie znaleziono zniżki dla gry w tym okresie.`,
  pl = `Ta oferta dnia została anulowana`,
  ml = `To zaproszenie zostało anulowane`,
  hl = `Jak działają zaproszenia?`,
  gl = `Jeżeli twoja gra zostanie zaproszona do udziału w ofercie dnia, otrzymasz e-mail i zobaczysz swoją grę powyżej. Oto jak ten proces będzie przebiegał od tego momentu:`,
  _l = `Wybierz dostępną datę w ciągu najbliższych 6\xA0miesięcy, która ci odpowiada.`,
  vl = `Twoja gra będzie widoczna na stronie głównej Steam oraz na odpowiednich stronach tagów przez 24 godziny, a zniżka będzie aktywna między 7\xA0a 14\xA0dniami w zależności od wybranego przez ciebie czasu trwania. Rozpocznie się o 10:00 czasu pacyficznego w wybranym przez ciebie dniu.`,
  yl = `Przy wyborze dostępnego terminu należy wskazać wysokość zniżki i wybrać pakiety, które mają zostać objęte promocją.`,
  bl = `Prosimy o wybranie wysokości zniżki (w procentach), która będzie równa najwyższej zniżce oferowanej przez ciebie w przeszłości lub od niej wyższa.`,
  xl = `Jeśli nie jesteś gotowy do zaplanowania oferty dnia teraz, to zaproszenie będzie znajdować się na panelu głównym ofert dnia. Pamiętaj o dacie zakończenia oferty.`,
  Sl = `Jeśli musisz zmienić datę, anulować lub masz pytania – %1$s`,
  Cl = `Skontaktuj się z nami tutaj.`,
  wl = `Najlepsze praktyki dotyczące ofert dnia`,
  Tl = `W wielu przypadkach korzystne okazać może się zsynchronizowanie zwiększonej widoczności i zniżki z innymi wcześniej zaplanowanymi działaniami takimi jak aktualizacja treści gry, transmisja na żywo lub wydarzenie społeczności.`,
  El = `Jeżeli chcesz zaplanować inne zniżki w ciągu miesiąca od wybranej oferty dnia, prosimy, by miały one równą wartość procentową. Wolelibyśmy widzieć taką samą lub lepszą ofertę w stosunku do twoich poprzednich dla tytułów wyróżnionych w ramach oferty dnia.`,
  Dl = `Aby dowiedzieć się więcej, sprawdź <1>dokumentację ofert dnia</1>.`,
  Ol = `Widoczność`,
  kl = `Oferty dnia wykorzystują obraz nagłówkowej miniatury i pojawi się on na stronie głównej Steam.`,
