  Wl = `Nie masz uprawnienia dla tej aplikacji`,
  Gl = `Brak wolnych miejsc`,
  Kl = `Wczytywanie informacji o zniżkach dla ofert dnia`,
  ql = `Istniejąca zniżka rozpocznie się w dniu %1$s`,
  Jl = `Wczytywanie zniżek pakietów`,
  Yl = `Istniejąca zniżka:`,
  Xl = `Twój produkt %1$s zostanie wyróżniony w ramach oferty dnia tego dnia z użyciem istniejącej zniżki %2$s.`,
  Zl = `Jeśli wolisz utworzyć nową zniżkę dla tej oferty dnia, usuń istniejącą zniżkę, przechodząc do %1$s i wprowadzając liczbę 0 jako procent zniżki lub wybierając inną datę dla oferty dnia.`,
