  b_ = `Anti-cheat`,
  x_ = `Jeśli twoja gra instaluje oprogramowanie anti-cheat po stronie klienta na poziomie jądra, to musisz poinformować użytkowników o tym fakcie w tym miejscu. Jeżeli masz swoje własne rozwiązanie anti-cheat, kliknij opcję „Inna” i podaj swoje własne informacje.`,
  S_ = `Jeśli twoja gra zawiera rozwiązanie anti-cheat po stronie klienta lub serwera, które nie jest oparte na jądrze, to wtedy to pole jest opcjonalne, ale ogólnie uważamy, że każda gra korzystająca z technologii zapobiegającej oszustwom skorzystałaby na poinformowaniu o tym graczy.`,
