  $_ = `Ten interfejs umożliwia przesłanie obrazu ilustrującego różnice pomiędzy edycjami twojej gry (np. standardowa w porównaniu do deluxe, GOTY itd.). Edycje zostaną pogrupowane z grą bazową na szczycie opcji zakupu i posortowane od najniższej do najwyższej ceny na stronie w sklepie. Aby poznać więcej informacji, zobacz <1>dokumentację zarządzania edycjami</1>.`,
