  jv = `Zanim przejdziesz dalej, potwierdź, że twoje obrazy spełniają wymogi. Jeśli prześlesz zasoby do oceny, a wymogi te nie zostaną spełnione, zespół ds. oceny Steam odrzuci je w procesie oceny i będziesz musiał je poprawić przed przejściem dalej. Po więcej informacji zajrzyj do naszej <1>dokumentacji dotyczącej zasobów graficznych</1>.`,
