  ob = `To działanie doda grafikę miniatury do opcji zakupu pakietu w sklepie w sposób podobny do tego, w jaki wyświetlana jest zawartość zestawów. Najpierw zostanie pokazana aplikacja bazowa, a potem inne dołączone aplikacje malejąco według ceny.`,
  sb = `Pomiń nazwę gry na początku nazw produktów na liście zawartości pakietu.`,
  cb = `Aby zredukować zbyteczne informacje i zwiększyć czytelność, pomiń nazwę gry plus znaki niedrukowalne oraz znaki łączące takie jak dwukropki i łączniki z początku nazw produktów takich jak DLC oraz ścieżki dźwiękowe, gdy są wymienione w obszarze zakupu pakietu. Przykładowo „Half-Life 2: Episode One” będzie wyświetlane jako „Episode One”. Ukryte są tylko dokładna nazwa gry bazowej oraz znaki niedrukowalne i powszechne separatory takie jak łączniki czy dwukropki.`,
