  gb = `Nie znaleziono spełniającego warunków wydarzenia. Wymagana jest wersja robocza lub niedawno (w ciągu ostatniego miesiąca) zamieszczone wydarzenie. <1>Sprawdź panel główny wydarzeń i ogłoszeń.</1>`,
  _b = `Umiejscowienie twojego logo zostało zapisane. Możesz opublikować te zmiany za pośrednictwem strony administratora strony produktu w sklepie.`,
  vb = `Zarządzanie zniżkami`,
