  JT = `<1>Wystąpił błąd podczas próby opublikowania tej zmiany ceny.</1><2>Spróbuj ponownie i skontaktuj się z Valve, jeśli problem będzie nadal występował.</2>`,
  YT = `widok kompaktowy`,
  XT = `Wybierz cenę poniżej, by ustawić ją dla wartości w dolarach amerykańskich i zastosować zalecane przeliczone ceny dla wszystkich pozostałych walut.`,
