  eE = `Pokaż pakiety zmienione lokalnie`,
  tE = `Nie możesz podnieść ceny subskrypcji. Jeśli musisz to zrobić, skontaktuj się ze Steam.`,
  nE = `Cena musi wynosić przynajmniej %1$s. Jeśli pozostanie ona poniżej tego minimum, to klienci z krajów korzystających z tej waluty nie będą mogli kupić tego pakietu.`,
  rE = `Twoja aktualna cena jest niższa niż ta, którą normalnie można ustalić dla tej waluty. Możesz zachować tę cenę w obecnej postaci, ale ograniczy to skalę zniżki, jaką możesz zastosować, aby utrzymać cenę po zniżce powyżej minimalnej dozwolonej kwoty transakcji.`,
  iE = `%1$s: cena w %2$s wysokości %3$s jest niższa od minimalnej ceny w %2$s (%4$s). Sprawdź, czy nie pominąłeś liczby. Wprowadź kwotę %4$s lub większą.`,
  aE = `%1$s: cena w %2$s w wysokości %3$s jest wyższa od aktualnie opublikowanej (%4$s). Ceny odnawialnej subskrypcji nie można podnieść, więc wprowadź kwotę %4$s lub mniejszą albo skontaktuj się ze Steam, jeśli chcesz ją podnieść.`,
  oE = `Jeszcze 1 zmiana ceny poniżej również wykracza poza dozwolony zakres.`,
  sE = `Jeszcze inne zmiany ceny (%1$s) poniżej również wykraczają poza dozwolony zakres.`,
  cE = `Cen tych nie można przesłać, dopóki nie zostaną poprawione. Sprawdź dokumentację <1>zasad dotyczących wyceny</1>, żeby poznać szczegóły.`,
  lE = `Na podstawie wybranej przez ciebie metody konwersji oraz ceny w dolarach amerykańskich, wprowadzona cena jest znacznie wyższa niż sugerowana (%1$s).`,
  uE = `Na podstawie wybranej przez ciebie metody konwersji oraz ceny w dolarach amerykańskich, wprowadzona cena jest znacznie niższa niż sugerowana (%1$s).`,
  dE = `Na podstawie wybranej przez ciebie metody konwersji i ceny w USD wprowadzona cena jest znacznie niższa od sugerowanej (%1$s). Ta cena ograniczy zniżki do maksymalnie %2$s%, aby cena po zniżce pozostała co najmniej na poziomie 0,49\xA0USD.`,
