  AL = `<Załącz ze wszystkich źródeł>`,
  jL = `Uwzględnij wszystkie gry ze wszystkich stron twórców (producentów/wydawców/serii) powiązanych z tą grą. Ręczne wyróżnianie pozwala wybrać konkretne strony twórcy do wyróżnienia. Algorytmiczne wyróżnianie będzie preferować pierwszego pasującego twórcę (w kolejności: seria, producent, wydawca) do wyświetlenia.`,
  ML = `Zależności DLC`,
  NL = `Czy to DLC wymaga innego elementu DLC do działania? Wybierz niezbędne elementy DLC do wyświetlania ich jako wymagane. Sklep automatycznie wyświetli tę zależność wraz z opcją zakupu wszystkich zależnych produktów razem.`,
