  GL = `Aby móc podjąć się tego zobowiązania, producenci muszą opisać graczom najważniejsze treści i daty wydania każdej z nich poniżej.`,
  KL = `Skorzystaj z ogólnej sekcji informacji o DLC powyżej, by ogólnie opisać przepustkę sezonową, korzystając z poniższych dat wydania treści dla poszczególnych wydań treści.`,
  qL = `Gdy będziesz gotowy poinformować graczy, że wydałeś treści w ramach przepustki sezonowej, użyj opcji „Oznacz jako wydane” poniżej i postępuj zgodnie z instrukcjami. Zapoznaj się z <1>dokumentacją wydania przepustki sezonowej</1>, by poznać więcej szczegółów.`,
  JL = `Stwórz nowe wydanie treści`,
