  PR = `Zawartość jest oznaczona jako wydana w przeszłości. Czy chcesz opcjonalnie wskazać, w jaki sposób zawartość jest już dostępna dla graczy?`,
  FR = `W jaki sposób te treści są udostępniane?`,
