  nz = `Kamień milowy został już wydany. Powiązanie z DLC lub wydarzeniem premierowym jest nadal możliwe i po prostu zaktualizuje prezentację bez zmiany daty wydania kamienia milowego.`,
  rz = `Powiązywanie po wydaniu kamienia milowego`,
  iz = `Kamień milowy został już oznaczony jako wydany dla klientów. Można wykorzystać to do powiązania brakującego DLC oraz wydarzenia premierowego. To działanie po prostu zaktualizuje prezentację po opublikowaniu.`,
  az = `Ankieta dotycząca spotkań branżowych z zespołem Steam`,
  oz = `Witaj, %1$s!%2$s Gdzie chciałbyś się z nami spotkać?`,
  sz = `Poniżej znajduje się kilka wydarzeń, w których członkowie zespołu Steam rozważają udział. Jeśli również rozważasz udział lub mieszkasz w pobliżu i interesuje cię spotkanie z nami, daj nam znać w formularzu poniżej. Użyjemy go do lepszego zaplanowania naszych harmonogramów podróży i wydarzeń. Jeśli zarejestrujesz się na wydarzenie, w którym planujemy wziąć udział, potraktujemy cię priorytetowo przed rozesłaniem zaproszeń do szerszego grona osób.`,
  cz = `Twoje informacje`,
  lz = `Daj nam znać, kim jesteś i podaj najlepszy sposób kontaktu z tobą:`,
