  _z = `Wskazuje wydarzenia, w których członkowie zespołu Steam planują wziąć udział. Co do pozostałych, wciąż nie podjęliśmy decyzji.`,
  vz = `Zaznacz każdy element z wydarzeniem, w którym zamierzasz uczestniczyć, nawet jeśli nie jest to jeszcze potwierdzone.`,
  yz = `W jakich innych wydarzeniach, które zostały przez nas pominięte powyżej, zamierzasz wziąć udział?`,
