  Oz = `Ankieta dot. Meet Steam: %1$s`,
  kz = `Czy masz jakieś opinie na temat dowolnej sesji Steam, w której wziąłeś udział w wynajmowanej przez Valve przestrzeni w Convene? To ankieta składająca się dosłownie z 1 pytania. Chcemy po prostu dowiedzieć się, czy w twojej pamięci wyryło się coś pozytywnego lub nie w związku z treściami, jakością, koordynacją czasową, lokalizacją lub tematyką sesji.`,
  Az = `Poprzednie wydarzenia: %1$s`,
  jz = `Organizatorzy konferencji chcieliby dowiedzieć się, czy planujesz wziąć udział i czy interesuje cię spotkanie z członkami Steam.`,
  Mz = `Inne konferencje`,
  Nz = `Wybierz zestaw do przypięcia`,
  Pz = `Brak przypiętych zestawów.`,
  Fz = `Brak opcji`,
  Iz = `Przeciągnij powyższe wymagane zasoby tutaj (maks. 50 MB).`,
  Lz = `Nieprawidłowe wymiary lub rozszerzenie pliku nie jest obsługiwane.`,
  Rz = `%1$s jest zduplikowanym zasobem. Usuń zasób, którego nie chcesz użyć.`,
  zz = `Wystąpił błąd podczas przesyłania tego pliku. Spróbuj ponownie.`,
  Bz = `Brak wymaganego zasobu.`,
  Vz = `Film przy uruchamianiu`,
  Hz = `Obraz podglądu`,
  Uz = `Wytyczne dla wideo`,
  Wz = `Rozdzielczość filmów przy uruchamianiu musi wynosić 1920\xA0×\xA01200 pikseli, by wyświetlały się na pełnym ekranie na Steam Decku. Filmy powinny być również tworzone z myślą o tym, że zostaną przycięte do wymiarów 1920\xA0×\xA01080 pikseli na większości ekranów w trybie Big Picture.`,
  Gz = `Ich długość powinna wynosić 3\xA0–\xA010\xA0s.`,
  Kz = `Mogą zawierać logo twojej gry, ale żaden inny tekst ani materiały marketingowe są niedozwolone.`,
  qz = `Wideo nie może być przezroczyste. Podczas eksportu konieczne może być wyłączenie kanału alfa.`,
  Jz = `Ostateczny plik musi mieć format .webm lub .mp4, a jego waga nie może przekroczyć 50\xA0MB. Zostanie skompresowany do lub .mp4 i nie większy niż 50MB. Plik zostanie skompresowany do rozsądnego rozmiaru.`,
  Yz = `Wytyczne dla dźwięku`,
  Xz = `Wszystkie filmy przy uruchamianiu zawierają też dźwięk. Dźwięk powinien być zaprojektowany w taki sposób, by współgrał z wyjściem małych głośników Steam Decka i nie powinien być zbyt głośny, by nie przytłaczać użytkownika przy uruchomieniu.`,
  Zz = `Pliki audio powinny być w formacie 16-bitowym i mieć częstotliwość 48\xA0kHz.`,
  Qz = `Dźwięk w finałowej wersji powinien wynosić -12\xA0dB w punkcie szczytowym oraz mieć -14 LUFS średniej głośności. Unormujemy dźwięk, by upewnić się, że nie jest zbyt głośny.`,
  $z = `Unikaj zbyt wielu średnio-niskich częstotliwości i weź pod uwagę zastosowanie filtru górnoprzepustowego (HPF) z początkiem w okolicy 40\xA0–\xA080\xA0Hz.`,
  eB = `Rozważ dodanie efektu zanikania na początku i końcu pliku dźwiękowego, aby uniknąć wszelkich „kliknięć” i nagłego urwania dźwięku na końcu filmu przy uruchomieniu.`,
  tB = `Wytyczne dla obrazu podglądu`,
  nB = `Prześlij nieruchomy obraz o rozdzielczości 1920\xA0×\xA01200 pikseli pochodzący z twojego filmu przy uruchamianiu. Ten obraz będzie używany do przedstawiania twojego filmu w ekwipunku użytkownika i ustawieniach klienta Steam.`,
  rB = `Dopuszczalne formaty to .png, .jpg i .webp.`,
  iB = `Obraz nie może być przezroczysty.`,
  aB = `Obraz nie może zawierać animacji – musi to być pojedyncza klatka.`,
  oB = `Powiązano z %1$s`,
  sB = `Tej nazwy nie można zmienić, gdy jest ona powiązana ze stroną twórcy. Jeśli musisz ją zedytować, najpierw ją rozdziel.`,
  cB = `Rozdziel grupę „%1$s” od linka „%2$s” dla tej gry. Efekt zostanie zastosowany natychmiastowo.`,
  lB = `*Wymaga zapisu`,
  uB = `Twoja strona serii nie może być ta sama, co twoja strona producenta ani wydawcy.`,
  dB = `Ta grupa jest już powiązana z wydawcą o innej nazwie. Zobacz instrukcje po prawej stronie.`,
  fB = `Ta grupa jest powiązana z inną aplikacją jako producent lub wydawca, więc sklep nie będzie wyświetlał jej jako serii. Zamiast tego powiąż grupę używaną wyłącznie dla tej serii.`,
  pB = `Powiązano jako producent lub wydawca dla:`,
  mB = `(jeszcze %1$s)`,
  hB = `Sklep łączy serię gier z jej stroną główną, gdy co najmniej dwie gry w sklepie kierują do niej jako do swojej serii. DLC, dema i programy się nie liczą. Do tego czasu nazwa serii gier jest wyświetlana bez linku.`,
  gB = `Wybierz stronę główną twórcy`,
  _B = `Powiąż „%1$s” ze stroną główną`,
  vB = `Wybierz istniejącą stronę główną twórcy lub grupę społeczności do połączenia z „%1$s” dla tej gry.`,
  yB = `Jest to istniejąca strona główna twórcy i jest ona połączona z inną grą dla tego konta partnerskiego.`,
  bB = `* Wskazuje, że ta strona twórcy jest już powiązana z inną grą dla twojego konta partnerskiego.`,
  xB = `Nie udało się ustalić konta partnerskiego dla tej gry, dlatego strony główne twórców powiązane z twoimi innymi grami nie są tutaj dostępne. Wymienione są tylko grupy społeczności, które do ciebie należą lub których jesteś oficerem.`,
  SB = `Brak strony głównej twórcy lub grupy społeczności, które można powiązać. Musisz być właścicielem lub oficerem grupy społeczności lub grupa ta musi być już powiązana z inną grą dla twojego konta partnerskiego.`,
  CB = `Nie można wczytać listy stron głównych twórcy. Spróbuj ponownie później.`,
  wB = `Niedziałające linki strony głównej twórcy`,
  TB = `Przedstawione linki do strony głównej twórcy istnieją w naszej bazie danych, ale nie odpowiadają żadnym powyższym nazwom. Możesz w bezpieczny sposób je usunąć.`,
