  JB = `Nagrania gier – zarządzanie ikonami osi czasu`,
  YB = `Z ikon utworzonych w tym miejscu można skorzystać z poziomu gry, by zaznaczyć określone momenty na osi czasu nagrania z gry. Steam ma również domyślny zestaw ikon, których możesz użyć. Szczegółowe informacje znajdziesz w dokumentacji.`,
  XB = `Utwórz nową ikonę`,
