  sV = `Używane przez wywołania API (maksymalna liczba znaków to %1$s). Musi składać się ze znaków alfanumerycznych (małą literą). Minimalna liczba znaków to 3. Dodatkowo obsługuje znaki „_” oraz „-”. Nie może zawierać pustych przerw.`,
  cV = `Identyfikator zawiera nieobsługiwane znaki. Musi składać się ze znaków alfanumerycznych (małą literą). Minimalna liczba znaków to 3. Dodatkowo obsługuje znaki „_” oraz „-”. Nie może zawierać pustych przerw.`,
  lV = `Identyfikator nie może zaczynać się od zarezerwowanego słowa „steam_” używanego dla oficjalnych ikon.`,
  uV = `Dla każdej ikony prześlij plik .png lub .svg i dodaj unikalny identyfikator, który będzie używany przez wywołania API.`,
  dV = `Ikona (pliki .SVG lub .PNG)`,
  fV = `Ikony SVG zostaną wyświetlone w polu o wymiarach 36 na 36 pikseli, więc utwórz swoje zasoby w odpowiedni sposób. Pliki PNG muszą mieć postać kwadratów o szerokości/wysokości od 24 do 256 pikseli.`,
  pV = `Ikony SVG zostaną wyświetlone w polu o wymiarach 36 na 36 pikseli, więc utwórz swoje zasoby w odpowiedni sposób. Pliki PNG muszą mieć postać kwadratów o szerokości/wysokości od 24 do 256 pikseli.`,
