  qV = `Jako że są to ikony publiczne, pewne lokalizacje mogą się do nich odwoływać, przez co nie można ich usunąć ani zmienić ich nazwy. W razie potrzeby możesz zaktualizować obraz.`,
  JV = `Utwórz nowe ikony jako „publiczne”, jeśli chcesz przygotować je do publicznego wydania.`,
  YV = `Ukryte ikony`,
  XV = `Skorzystaj z ukrytych ikon do testów przed opublikowaniem. Jeśli musisz ograniczyć do nich dostęp, użyj poniższych zestawów do powiązania określonych ikon z konkretnymi gałęziami kompilacji.`,
  ZV = `Skorzystaj z ukrytych ikon do testów przed opublikowaniem.`,
