  tH = `Pobierz, by przetestować lokalnie`,
  nH = `Tworzy pojedynczy plik .SVG, którego Steam może użyć do renderowania ikon. Spowoduje to utworzenie pliku zawierającego zarówno wszystkie ikony publiczne, jak i ikony z ukrytego zestawu.`,
  rH = `Utwórz nowe ikony jako „ukryte”, jeśli chcesz przeprowadzić test przed publicznym wydaniem.`,
