  oH = `Utwórz nowy zestaw dla gałęzi`,
  sH = `Zestawy dla gałęzi pomagają zarządzać testowaniem ukrytych ikon, ograniczając dostęp ikon wyłącznie do kompilacji na określonych gałęziach.`,
