  gH = `Duplikacja znacznika osi czasu powiodła się. `,
  _H = `Opcjonalnie wybierz jedną lub więcej gałęzi, z którymi te przedmioty mają zostać powiązane. Każdy gracz korzystający z wybranych gałęzi będzie widzieć te zasoby. Jeśli zostanie wybrana dowolna gałąź niechroniona hasłem, to potraktujemy ikony jako widoczne publicznie.`,
  vH = `W liście gałęzi nie wprowadzono żadnych zmian.`,
