  ZH = `Aby uzyskać najlepsze rezultaty, ikony osiągnięć powinny być plikami PNG o wymiarach 256\xA0×\xA0256 pikseli. Ich wymiary mogą mieć najmniej 64\xA0×\xA064 piksele, ale zalecamy użycie większych wymiarów oraz by ikony zdobytych osiągnięć były kolorowe, a niezdobytych w odcieniach szarości.`,
  QH = `Z racji tego, że osiągnięcia pojawiają się w wielu miejscach w Społeczności Steam, ich nazwy oraz ikony muszą być odpowiednie dla wszystkich grup wiekowych. Valve może całkowicie usunąć grę ze sklepu, jeżeli dostępne dla niej osiągnięcia łamią <1>wytyczne dla zawartości społeczności</1> lub są obraźliwe w jakikolwiek inny sposób.`,
  $H = `Aby w pełni włączyć osiągnięcia i ukończyć listę kontrolną wydania, musisz także zaznaczyć odpowiednie pole w sekcji <1>„Obsługiwane funkcje”</1>.`,
  eU = `Przed wydaniem <1>możesz zobaczyć podgląd swoich osiągnięć tutaj</1>. Status osiągnięć będzie wyświetlany równolegle.`,
